def alert_if_needed(live, reference):
    report = {
        "missing_rate_delta": live.missing_rate - reference.missing_rate,
        "approval_rate_delta": live.approval_rate - reference.approval_rate,
        "p95_latency_ms": live.p95_latency_ms,
        "model_version": live.model_version,
        "slice": live.slice_name,
    }
    high = abs(report["approval_rate_delta"]) > 0.08 and live.sample_size >= 500
    if high:
        return {"severity": "high", "owner": "risk-model-oncall", "report": report}
    return {"severity": "watch", "report": report}

